import SwiftUI

/// Versioned offline copy of the published policy; no automatic network requests.
struct PrivacyPolicyView: View {
    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 24) {
                Label("Your privacy", systemImage: "hand.raised.fill")
                    .font(AppTheme.displayTitle).accessibilityAddTraits(.isHeader)
                Text("Offline copy · Effective 30 October 2026")
                    .font(.subheadline).foregroundStyle(.secondary)
                    .accessibilityIdentifier("privacyPolicy.effectiveDate")
                Text("Operated by Vasanthi D · support@neuralluna.com")
                    .font(.subheadline).textSelection(.enabled)
                if let policyURL = URL(string: "https://neuralluna.com/privacy.html") {
                    Link("Read the current policy online", destination: policyURL)
                        .accessibilityIdentifier("privacyPolicy.online")
                }
                policySection("Who this policy covers", "Vasanthi D operates Nam Illam (நம் இல்லம், “Our home”) under the NeuralLuna brand. This policy covers the iOS app, neuralluna.com, namillam.neuralluna.com and support enquiries. Contact the operator about support, privacy or complaints at support@neuralluna.com. The app was previously developed as LunaHearth; some screenshots and earlier builds use that name.")
                policySection("Your household information", "The app stores the information you enter to organise your household: member display names and roles, appointments, shopping and pantry items, quantities and dates, meal plans, stores, purchase amounts and currencies, rooms and measurements, belongings, warranty and maintenance details, and associated notes. Records have identifiers and timestamps used to save and synchronise changes. Core records are stored locally on your device. There is no separate Nam Illam login or publisher-operated household-content database.")
                policySection("Why information is used", "Information supports the features you choose: showing household plans, tracking pantry and shopping items, organising rooms and belongings, calculating recorded spending, suggesting meals or item details, and arranging notifications. Selected records are processed for optional Apple connections, backup and sharing only through those features. The reviewed app does not contain advertising, behavioural analytics, data-broker integrations or a remote AI service.")
                policySection("Optional iCloud backup and sharing", "When you enable private household sync, supported records are sent to Apple CloudKit using your Apple Account. Invited participants access the shared home through Apple sharing permissions. A member profile alone does not grant access. A separate manual backup saves a snapshot in your private CloudKit database. These are distinct from Apple’s device backups. Connectivity, account access and Apple service conditions affect availability; offline edits wait for successful sync. Document and room-scan files are not supported by the reviewed backup/sharing path. Do not treat it as a complete file backup.")
                policySection("Who can see a shared household", "People with access to a shared home can see its supported plans, lists, rooms, belongings and related details. Share only with people you trust and review participants before adding personal information. Participants may take screenshots or retain copies. Revoking access or deleting the cloud home does not remotely erase copies already received. Changes and category deletions may synchronise to other shared devices.")
                policySection("Apple Calendar and Reminders", "Connections are optional. The current implementation asks for full system access to Calendar or Reminders, then reads the calendars or lists you select in the app. It can write appointments or reminders you choose and update selected reminders. New reminders are saved in the selected Apple Reminders list, without a duplicate new household task. Connected Apple entries follow the account and sharing settings of their destination, which may include another account provider configured on your device. Source identifiers and preferences are kept locally. Reading selected Apple entries does not automatically add them to household CloudKit backups. Disconnecting does not delete existing Apple entries.")
                policySection("Photos, receipt recognition and on-device intelligence", "Camera and selected photos are used when you start receipt or kitchen-photo workflows. Text recognition, image analysis and optional Apple Foundation Models assistance run on the device in the reviewed implementation. Input may include your request and the relevant item names or records needed for that feature. The app does not send these prompts to a third-party AI endpoint. Scan images are used during the workflow; review and confirm extracted details before saving records. Selected originals remain subject to the source photo library’s settings. No complete document vault or document-file cloud backup is promised by this policy.")
                policySection("Permissions and notifications", "You can decline optional camera, photo, Calendar, Reminders and notification access. Features needing that access will be limited; core manual household organisation remains available. Change permissions in iOS Settings. Notification content can include household details and may appear on your Lock Screen according to your device settings. Review notification previews if other people use or can see your device.")
                policySection("Public app settings", "Separately from optional household sync, the app periodically reads a fixed public CloudKit configuration record containing feature settings, notices and help text. The request does not include household content in its application payload. Settings are cached locally so manual features can remain available offline. Apple may process connection and service information under its own policies. This operational-settings feature is not a dynamic privacy-policy download.")
                policySection("Local AI diagnostics", "AI Status stores the latest feature result categories and timestamps locally for troubleshooting. These diagnostic entries do not contain prompts, photos, generated answers or raw error descriptions. Clear them in More → AI Status. The reviewed app does not automatically send this history to the publisher. Apple may separately process system diagnostics according to your Apple settings.")
                policySection("Retention and deletion", "Local household records remain until you remove them using the app’s controls or otherwise remove the app’s local storage. There is no automatic age-based expiry for ordinary household records in the reviewed code. More → Privacy & data → Clear household data provides category cleanup and a confirmed local reset; connected cloud homes can block a local reset to protect shared data. Category deletion propagates when household sync is enabled. Cloud backup snapshots, live cloud homes, system backups, Apple Calendar/Reminders entries and recipient copies have separate lifecycles. Deleting one does not erase all others. Synced deletions retain a marker with record identifiers, type and timestamps to prevent old copies reappearing; the deletion marker’s content payload is empty. The reviewed code has no scheduled expiry for these markers.")
                policySection("Cloud copies and backup retention", "Manage manual backups separately through More → Privacy & data → Manage backups. A new backup replaces the referenced prior snapshot, but failed cleanup can leave older generations; the explicit delete-backups action targets the app’s manual backup generations. The owner can separately delete a live synced home from iCloud in iCloud sync & data. This ends sharing and keeps local device copies. Uninstalling the app, revoking permission or signing out is not a request to erase every external copy. Review Apple device backups and destination apps separately.")
                policySection("Support enquiries", "If you email support@neuralluna.com, we receive your email address, message and attachments to answer questions, troubleshoot and handle privacy requests. The mailbox is hosted by Hostinger Mail and accessed by Vasanthi D. Resolved support requests are deleted after 90 days unless needed for an ongoing dispute or a legal obligation. Email providers may retain their own backup or service records under their policies. Send only necessary details and redact screenshots. Do not send passwords, verification codes, invitation links or full household backups.")
                policySection("This website and hosting", "The websites neuralluna.com and namillam.neuralluna.com are hosted by Hostinger. Hosting and network delivery process connection information, such as IP addresses and request logs, for delivery, security and operation. Hostinger manages its service logs and retention under its privacy policy at https://www.hostinger.com/legal/privacy-policy. The website code has no analytics SDK, advertising, contact-submission backend, embedded third-party media or visitor account system. FAQ search and screenshot controls run in your browser. Email links open your mail app and do not send automatically.")
                policySection("Cookies and browser storage", "The website’s own scripts do not set cookies or use localStorage or sessionStorage. Hosting infrastructure may use cookies or other service mechanisms under the provider’s policies. Your browser may cache pages and images. Visiting the site does not signify consent to advertising tracking. If tracking, forms or embedded services are introduced, this notice and any required choices will be updated.")
                policySection("Providers and processing locations", "Apple handles optional cloud and device services. Hostinger provides website hosting and Hostinger Mail handles the support mailbox; your own email provider also handles messages you send. These providers may process information outside India under their service arrangements. India-only app availability does not mean India-only storage. We do not sell household information, use advertising trackers or operate a remote AI service. No particular storage country or guaranteed security is promised.")
                policySection("Children and other household members", "Nam Illam is designed for adult-managed household organisation, not a child account or social networking service. Member profiles are household records. Do not enter or share unnecessary information about children or other people. A parent, guardian or responsible adult should supervise use and obtain permissions required by applicable law. Contact support@neuralluna.com if you believe a child has sent personal information to support so we can review and address it.")
                policySection("Privacy requests and complaints", "Contact Vasanthi D at support@neuralluna.com to request access, correction or deletion of information you supplied to support, withdraw consent where applicable, or raise a privacy concern. Describe your request without including household content or identity documents unnecessarily. We may ask for proportionate information to verify the request and will respond within applicable legal deadlines. Support cannot retrieve or erase records that exist only on your device or in your private Apple services; use the app’s data controls and Apple settings for those copies. Your statutory rights and rights to approach a competent authority remain unaffected.")
                policySection("Changes to this policy", "This policy shows its effective and revision dates above. Material changes will be communicated appropriately, and fresh consent will be requested where required before new processing starts. Earlier app builds may contain an older offline policy; this page describes the current published policy. Contact support@neuralluna.com for questions.")
            }.padding(24).frame(maxWidth: 760).frame(maxWidth: .infinity)
        }
        .navigationTitle("Privacy policy").navigationBarTitleDisplayMode(.inline)
        .background(AppTheme.canvas)
        .accessibilityIdentifier("privacyPolicy.screen")
    }
    private func policySection(_ title: String, _ body: String) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title).font(.headline).accessibilityAddTraits(.isHeader)
            Text(body).font(.body).textSelection(.enabled).fixedSize(horizontal: false, vertical: true)
        }.frame(maxWidth: .infinity, alignment: .leading)
    }
}
